-- Private stock discovery metadata. No licensed file, preview, key or download URL is stored.
create table public.studio_asset_candidates(
 provider text not null check(provider='magnific'),
 external_id text not null check(external_id ~ '^[0-9]{1,20}$'),
 title text not null check(char_length(title) between 1 and 150),
 author text not null check(char_length(author) between 1 and 100),
 source_url text not null check(source_url ~ '^https://www[.]magnific[.]com/[a-z-]+/[a-z0-9-]+_[0-9]+[.]htm$'),
 quoted_credits integer not null check(quoted_credits>=0),
 status text not null default 'review' check(status in ('review','rejected')),
 discovered_at timestamptz not null default now(),
 primary key(provider,external_id)
);
alter table public.studio_asset_candidates enable row level security;
revoke all on public.studio_asset_candidates from public,anon,authenticated;
grant select on public.studio_asset_candidates to authenticated;
create policy studio_candidate_editor_read on public.studio_asset_candidates for select to authenticated using((select studio_private.is_editor()));
-- Only private curation; no public stock serving or license grant.
